async function migrateActiveVersion(){if(!job)return;if(!await dialog(t('Migrasikan versi proyek?'),el('p',{},t('Checkpoint revisi aktif dibuat dahulu. Semua hasil dan riwayat dipertahankan; QA dan persetujuan perlu diperiksa ulang.')),t('Cadangkan dan migrasikan versi')))return;await checkpoint();if(!checkpointReceipt)throw new Error(t('Checkpoint belum tersedia.'));const prior=job,documents:Document[]=[];for(const entry of prior.documents){const fresh=await revalidateDocument(await hydrateDocument(entry),prior);documents.push(entry.payload?await parkDocument(fresh):fresh);}const candidate={...prior,documents,log:[...prior.log]};migrateVersion(candidate,checkpointReceipt,running);await saveJob(candidate);job=candidate;engine.reset();ready=undefined;engineFingerprint='';if(job.documents.length)await openDocument(selectedDoc);message(t('Versi dimigrasikan. Hasil dan riwayat dipertahankan; periksa pemetaan dan QA.'));}
