async function approve(){const s=current();if(!s||!job||s.target===undefined)return;if(editorDrafts.has(s.id))throw new Error(t('Simpan atau batalkan edit sebelum meninjau hasil committed.'));if(s.findings.some(f=>['critical','major'].includes(f.severity)&&!f.resolved))throw new Error(t('Selesaikan temuan critical/major terlebih dahulu.'));const name=el('input',{class:'input',placeholder:t('Nama / inisial penelaah'),'aria-label':t('Nama penelaah')}),check=el('input',{type:'checkbox'});const ok=await dialog(t('Catat tinjauan manusia'),el('div',{},el('p',{},t('Persetujuan hanya berlaku untuk revisi sumber dan target yang tampil. Jangan menandai hasil yang belum Anda periksa.')),name,el('label',{class:'checkline'},check,t('Saya sudah membandingkan sumber dan target, termasuk makna, syarat, dan rujukannya.'))),t('Setujui segmen'));if(!ok)return;if(!name.value.trim()||!check.checked)throw new Error(t('Nama penelaah dan konfirmasi pemeriksaan diperlukan.'));s.reviewer=name.value.trim();s.reviewHash=await sha256(s.source+'\0'+s.target);s.status='HUMAN_REVIEWED';audit(job,'HUMAN_REVIEW',s.id+' · '+s.reviewer);await persist();message(t('Tinjauan manusia tercatat untuk segmen ini.'));}
